function Stop-Now([string]$Message) {
    throw "STOP: $Message"
}

function Assert-Last([string]$Message) {
    if ($LASTEXITCODE -ne 0) {
        Stop-Now $Message
    }
}

function Get-FreeGB {
    [math]::Round((Get-PSDrive C).Free / 1GB, 2)
}

function Expand-GzipBase64ToFile(
    [string]$Base64,
    [string]$Destination
) {
    $compressed = [Convert]::FromBase64String($Base64)
    $input = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream(
        $input,
        [IO.Compression.CompressionMode]::Decompress
    )
    $output = New-Object IO.MemoryStream
    $gzip.CopyTo($output)
    $gzip.Dispose()
    $input.Dispose()
    [IO.File]::WriteAllBytes($Destination, $output.ToArray())
    $output.Dispose()
}

$Phase1Payload = @'

'@

$Phase2Payload = @'

'@

Write-Host "`n========================================================" -ForegroundColor Cyan
Write-Host "TAYQAN FINAL PATCH — APPLY ONLY" -ForegroundColor Cyan
Write-Host "NO MIGRATION EXECUTION / NO STRIPE LIVE MUTATION" -ForegroundColor Cyan
Write-Host "========================================================" -ForegroundColor Cyan

Write-Host "`n=== 1. VERIFY EXACT WORKTREE ===" -ForegroundColor Cyan

if (-not (Test-Path -LiteralPath $Worktree)) {
    Stop-Now "Worktree does not exist: $Worktree"
}

git -C $Worktree rev-parse --is-inside-work-tree
Assert-Last "Not a Git worktree."

$branch = (git -C $Worktree branch --show-current).Trim()
$head   = (git -C $Worktree rev-parse HEAD).Trim()
$status = @(git -C $Worktree status --porcelain)

Write-Host "BRANCH: $branch"
Write-Host "HEAD:   $head"

if ($branch -ne $ExpectedBranch) {
    Stop-Now "Wrong branch. Expected $ExpectedBranch"
}

