    Stop-Now "Wrong base HEAD. Expected $ExpectedHead"
}

if ($status.Count -gt 0) {
    $status | ForEach-Object { Write-Host $_ -ForegroundColor Yellow }
    Stop-Now "Worktree is not clean before patching."
}

Write-Host "PASS: exact clean TAYQAN feature branch." -ForegroundColor Green

Write-Host "`n=== 2. DISK / DEPENDENCY SAFETY ===" -ForegroundColor Cyan

