$phase2 = Join-Path $RuntimeDir "phase2_complete_workflow_patcher.mjs"

Expand-GzipBase64ToFile $Phase1Payload $phase1
Expand-GzipBase64ToFile $Phase2Payload $phase2

$hash1 = (Get-FileHash -LiteralPath $phase1 -Algorithm SHA256).Hash.ToLowerInvariant()
$hash2 = (Get-FileHash -LiteralPath $phase2 -Algorithm SHA256).Hash.ToLowerInvariant()

Write-Host "PHASE 1 SHA256: $hash1"
Write-Host "PHASE 2 SHA256: $hash2"

if ($hash1 -ne $ExpectedPhase1Hash) {
    Stop-Now "Phase 1 payload integrity failure."
}

if ($hash2 -ne $ExpectedPhase2Hash) {
    Stop-Now "Phase 2 payload integrity failure."
}

Write-Host "PASS: both patchers match the audited V2 payload." -ForegroundColor Green

Write-Host "`n=== 4. APPLY PAID HIRE / STRIPE ENTITLEMENT / INTAKE ===" -ForegroundColor Cyan

